export const SINGEN_WISSEN = {"anatomie_kurz":"Das Zwerchfell ist bei jeder Atmung der wichtigste Einatemmuskel. ‚Bauchatmung‘ und ‚Brustatmung‘ beschreiben nur, was man außen sieht: Bauch und untere Rippen – oder obere Brust und Schultern.","atemstuetze":{"belegstaerke":{"bestimmte_technik_besser":"unbelegt","mechanik_druck":"gut","saengermuster":"mittel (kleine Messstudien)"},"erklaerung_ui":"Beim Singen soll der Luftdruck unter den Stimmlippen gleichmäßig bleiben – auch wenn die Lunge leerer wird. Am Anfang einer Phrase drückt die volle Lunge von selbst (wie ein Ballon): Dann bremsen die Einatemmuskeln ein wenig, die Rippen bleiben weit. Später helfen die Bauchmuskeln aktiv nach. Dieses Zusammenspiel nennt man Atemstütze.","mythen_ui":[{"aussage":"„Man singt mit dem Zwerchfell.“","richtig":"Das Zwerchfell ist ein Einatemmuskel. Beim Singen lässt es kontrolliert nach (bremst), die Luft schieben die Rückstellkraft der Lunge und die Bauchmuskeln."},{"aussage":"„Beim Singen den Bauch rausdrücken.“","richtig":"In Messungen geht die Bauchwand bei geübten Sängern vor dem Ton eher leicht nach innen; die Rippen bleiben weit. Pressen ist nicht nötig."},{"aussage":"„Je mehr Luft, desto besser.“","richtig":"Sänger beginnen Phrasen meist bei etwa 70 % der möglichen Luft, nicht bei 100 %. Zu voll kann die Stimme hauchig machen."}],"name_ui":"Atemstütze","quellen":["BT44","GA09","GA12","GA13","GA15","GA17","GA20","GA22","GA27"],"was_belegt_ist":["Die Rückstellkraft der Lunge ist bei hohem Volumen groß, bei niedrigem klein bzw. umgekehrt gerichtet – deshalb muss die Muskelarbeit während einer Phrase wechseln (Physiologie, Lehrbuch).","Geübte klassische Sänger nutzen mehr Bauchanteil, steuern Brustkorb und Bauch zeitversetzt und ziehen die Bauchwand kurz vor dem Ton leicht ein (7 Sänger vs. 4 Ungeübte, BT44).","Brustkorb und Zwerchfell arbeiten beim Singen als getrennt gesteuerte Einheiten; bei Tonsprüngen nach unten zieht sich das Zwerchfell kurz zusammen, um den Druck zu senken (Echtzeit-MRT, 7 Sänger, GA15).","Das Zwerchfell wurde bei allen 4 gemessenen Profi-Sängern beim Singen gezielt eingesetzt, vor allem bei schnellen Druckwechseln (Druckmessung, GA20). Atemstütze als Zusammenspiel von Ein- und Ausatemmuskeln ist die gängige Lehrmeinung (GA27).","Rippen und Bauch gleichen sich aus: Wurden Sängerinnen angewiesen, den Bauch rein oder raus zu nehmen, blieb das Lungenvolumen gleich, weil der Brustkorb gegensteuerte (GA22).","Jeder Sänger hat sein eigenes Muster; eine einheitliche ‚richtige‘ Atemtechnik zeigte sich nicht (GA09, BT44)."],"was_nicht_belegt_ist":["Dass eine bestimmte Schule (Bauch raus / Bauch rein / Flanken) besser klingt oder gesünder ist.","Dass Hochatmung den Kehlkopf verspannt – plausibel und Lehrmeinung, aber kaum kontrolliert untersucht.","Dass Atemübungen allein die Stimme verbessern; bei Stimmstörungen sind Atemübungen nicht für alle Fälle belegt."]},"einsingen_dauer":{"abkuehlen":"Nach langem Singen 3–5 Minuten sanfte Gleittöne durch den Strohhalm oder Lippenflattern (Praxis; eine Arbeit beschreibt ein solches Abkühl-Programm, GA30).","beleg":"Kleine Studie (9 Gesangsstudierende): 5 und 10 Minuten Einsingen brachten das beste Selbstgefühl und bei Frauen einen etwas größeren Tonumfang; Fachhörer hörten keinen Unterschied (GA28). Strohhalm-Einsingen bei 26 Ungeübten: Einschwingdruck am niedrigsten nach etwa 10 Minuten (GA26). Übersicht Sprechstimme: empfohlen 15–30 min, aber wenige Studien (GA29).","belegstaerke":"schwach","empfehlung_app":"5–10 Minuten; Kurz-Variante 3 Minuten."},"gesundheit_singen_kurz":"Singen in der Gruppe kann bei Lungenkrankheit (COPD) die körperliche Lebensqualität etwas verbessern; Atemnot wurde nicht messbar besser, Belege schwach (BT45). Einatem-Muskeltraining bei Musikern: Einatemkraft stieg, bei einem Drittel nicht (BT35)."};
export const VERGLEICH = {"atemarten":[{"id":"zwerchfell_bauch","muskeln_ein":{"zwerchfell":3,"zwischenrippen_aussen":1},"name_ui":"Zwerchfell-/Bauchatmung","ui_kurztext":"Atme so, dass sich der Bauch hebt – die Schultern bleiben unten.","was_sieht_man":"Bauch wölbt sich beim Einatmen leicht nach vorn, untere Rippen weiten sich etwas, Schultern bleiben ruhig."},{"id":"flanken","muskeln_ein":{"zwerchfell":3,"zwischenrippen_aussen":2},"name_ui":"Flankenatmung (Zwerchfell + untere Rippen)","ui_kurztext":"Hände an die unteren Rippen: Beim Einatmen schieben sie sich zur Seite. Schultern bleiben unten.","was_sieht_man":"Taille und untere Rippen weiten sich zur Seite und nach hinten; Bauch geht etwas mit, Brust und Schultern bleiben ruhig."},{"id":"brust_hoch","muskeln_ein":{"brustmuskel_klein":2,"kopfwender":3,"trapez_oben":2,"treppenmuskeln":3,"zwerchfell":1,"zwischenrippen_aussen":2},"name_ui":"Brust-/Hochatmung","ui_kurztext":"Wenn sich die Schultern beim Einatmen heben, atmest du hoch in die Brust. Beim Singen besser tiefer atmen.","was_sieht_man":"Obere Brust und Schlüsselbeine heben sich, Schultern gehen hoch, Bauch bewegt sich kaum oder zieht sich sogar ein."},{"id":"normal_gemischt","name_ui":"Normale Atmung (gemischt)","was_sieht_man":"Brustkorb und Bauch bewegen sich beide ein wenig."}],"hinweis_ui":"Das Zwerchfell arbeitet bei beiden – nur unterschiedlich stark.","titel":"Bauch- und Brustatmung im Vergleich","zeilen":[{"bauch_flanke":"Bauch, Taille, untere Rippen","brust_hoch":"Obere Brust, Schlüsselbein, Schultern","merkmal":"Was hebt sich?"},{"bauch_flanke":"Zwerchfell","brust_hoch":"Hilfsmuskeln an Hals und Brust","merkmal":"Hauptmuskel"},{"bauch_flanke":"viel bei wenig Mühe","brust_hoch":"weniger bei mehr Mühe","merkmal":"Luft pro Atemzug"},{"bauch_flanke":"locker","brust_hoch":"angespannt","merkmal":"Hals und Schultern"},{"bauch_flanke":"Ruhe, Singen, lange Sätze","brust_hoch":"kurz bei großer Anstrengung","merkmal":"Gut für"}]};
export const LUNGE = {"herkunft":"buch_zusatz","kapitel":"Kap. 4: Lunge (laut Zusammenfassungen)","realistisch":{"belege":["Hochintensives Einatem-Muskeltraining (80 % des Maximaldrucks) erhöhte in einem kleinen RCT die Lungenvolumina etwas, 60 % nicht (BT34) – vorläufig.","Atemmuskeltraining verbessert die Ausdauerleistung Gesunder, weniger Trainierte profitieren mehr; Studien oft ohne Schein-Training (BT32).","Hochresistenz-Einatemtraining (30 Atemzüge, ~5 min, 6 Tage/Woche, 6 Wochen) senkte bei Menschen mit erhöhtem Blutdruck den systolischen Wert um ~9 mmHg (kleines RCT mit Gerät, BT33).","Anhaltezeit steigt in 2 Wochen deutlich – durch Gewöhnung an den Atemdrang und stärkeren Tauchreflex, nicht durch ‚mehr Lunge‘ (BT26)."],"kurz":"Die Lungengröße (Total- und Vitalkapazität) wird vor allem von Körpergröße, Geschlecht, Alter und Anlage bestimmt und ändert sich bei gesunden Erwachsenen durch Atemübungen kaum. Trainierbar sind: Kraft und Ausdauer der Atemmuskeln, ein ruhiges und sparsames Atemmuster, die Ruhe beim Atemdrang (CO2) und damit die Anhaltezeit. Dass Menschen mit besserer Lungenfunktion im Mittel länger leben, ist ein Zusammenhang aus Beobachtungsstudien – kein Beweis, dass Atemübungen das Leben verlängern.","ui_text":"Deine Lunge wird durch Atemübungen kaum größer. Was sich trainieren lässt: die Ruhe beim Atemdrang und damit die Anhaltezeit – und mit einem Atemtrainer-Gerät die Kraft der Einatemmuskeln."},"volumen":{"atemzuege_pro_min_ruhe":{"bereich":"12–20","hinweis":"Lehrbuch-Richtwert"},"atemzug_ruhe_l":{"frauen":0.4,"pro_kg":"≈ 7 ml/kg","quelle":"GA06","wert":0.5},"hinweis":"Richtwerte für Erwachsene; stark abhängig von Größe, Geschlecht, Alter, Training. Für die Grafik als Maßstab, nicht als Messung des Nutzers.","klassisch_singen":{"belegstaerke":"mittel (eine Messstudie, Zahlen aus Zusammenfassung)","ende_prozent_vk":34,"hinweis":"Ende 34 % VK ≈ 1,2 + 0,34·4,8 ≈ 2,8 L, also knapp unter der Ruhelage: Am Phrasenende wird aktiv ausgeatmet.","phrase_mittel_s":5.2,"quelle":"GA13","start_prozent_vk":70},"restluft_l":{"bereich":"1,0–1,2","name_ui":"Restluft (bleibt immer drin)","quelle":"GA07","wert":1.2},"ruhe_ausatemlage_l":{"name_ui":"Ruhelage (nach normalem Ausatmen)","quelle":"GA07","wert":3},"sprechen":{"belegstaerke":"mittel (Zahlen aus Sekundärquelle)","ende_prozent_vk":"30–50","gesamtbereich_prozent_vk":"20–70","quelle":"GA14","start_prozent_vk":"50–60"},"totale_kapazitaet_l":{"name_ui":"Lunge ganz voll","quelle":"GA07","wert":6},"vitalkapazitaet_l":{"hinweis":"abgeleitet: 6,0 − 1,2","name_ui":"Größter Atemzug (ganz aus → ganz ein)","wert":4.8},"zu_voll_ist_nicht_besser":"Bei sehr hohem Lungenvolumen schließen die Stimmlippen im Mittel etwas schwächer und der Kehlkopf steht tiefer (Messung an 24 Ungeübten). Die Stimme kann hauchiger werden – ‚ganz voll tanken‘ ist fürs Singen nicht nötig.","zu_voll_quelle":"GA17"}};
